function dump(node, depth) {
  const o = {id: node.id, name: node.name, type: node.type, w: Math.round(node.width), h: Math.round(node.height)};
  if (node.type === 'TEXT') { o.chars = node.characters; o.font = node.fontName; o.size = node.fontSize; try{o.fills = JSON.parse(JSON.stringify(node.fills));}catch(e){} }
  if ('fills' in node && node.type !== 'TEXT') { try{o.fills = JSON.parse(JSON.stringify(node.fills));}catch(e){} }
  if ('strokes' in node) { try{o.strokes = JSON.parse(JSON.stringify(node.strokes)); o.strokeWeight = node.strokeWeight;}catch(e){} }
  if ('cornerRadius' in node) o.cornerRadius = node.cornerRadius;
  if ('layoutMode' in node && node.layoutMode !== 'NONE') { o.layoutMode = node.layoutMode; o.itemSpacing = node.itemSpacing; o.padding = [node.paddingTop, node.paddingRight, node.paddingBottom, node.paddingLeft]; o.primaryAlign = node.primaryAxisAlignItems; o.counterAlign = node.counterAxisAlignItems; }
  if ('children' in node && depth > 0) o.children = node.children.map(c => dump(c, depth-1));
  return o;
}
